        client_options={"api_endpoint": f"{config['location']}-documentai.googleapis.com"})


def get_processor_path(client, project_id, location, processor_id):
    return client.processor_path(project_id, location, processor_id)

from google.cloud.documentai_v1beta3.types import Document


def normalize_response(response):
    normalized_response = {
        "text": response.document.text,
        "pages": []
    }
    for page in response.document.pages:
        page_data = {
            "blocks": [],
            "tables": [],
            "key_value_pairs": []
        }
        for block in page.blocks:
            page_data["blocks"].append({
                "block_type": block.block_type,
                "text": block.text,
                "confidence": block.confidence,
                "bounding_box": block.bounding_box
            })
        for table in page.tables:
            table_data = {
                "header_rows": [],
                "body_rows": [],
                "footer_rows": []
            }
            for row in table.header_rows:
                table_data["header_rows"].append([cell.text for cell in row.cells])
            for row in table.body_rows:
                table_data["body_rows"].append([cell.text for cell in row.cells])
            for row in table.footer_rows:
                table_data["footer_rows"].append([cell.text for cell in row.cells])
            page_data["tables"].append(table_data)
        for key_value_pair in page.key_value_pairs:
            page_data["key_value_pairs"].append({
                "key": key_value_pair.key.text,
                "value": key_value_pair.value.text
            })
        normalized_response["pages"].append(page_data)
    return normalized_response

from google.cloud import documentai


def extract_fields(text, config):
    client = documentai.DocumentProcessorServiceClient(
        client_options={"api_endpoint": f"{config['location']}-documentai.googleapis.com"})
    name = client.processor_path(config["project_id"], config["location"], config["processor_id"])
    response = client.process_document(request={
        "name": name,
        "raw_document": documentai.RawDocument(
            content=text.encode('utf-8'), mime_type="text/plain")
    })
    fields = {}
    for page in response.document.pages:
        for key_value_pair in page.key_value_pairs:
            key = key_value_pair.key.text
            value = key_value_pair.value.text
            fields[key] = value
    return fields

from google.cloud import language


def embed_text(text):
    client = language.LanguageServiceClient()
    document = language.Document(content=text, type_=language.Document.Type.PLAIN_TEXT)
    response = client.analyze_sentiment(request={
        "document": document
    })
    sentiment = response.document_sentiment.score
    return sentiment
